select '1. the team access switches are there' as check, case when to_regclass('public.team_access') is not null and to_regprocedure('public.staff_can(text)') is not null then 'OK' else 'PROBLEM - 0044 did not run' end as result; select '2. only the CEO can change them' as check, case when to_regclass('public.team_access') is not null and not exists ( select 1 from pg_policies where schemaname = 'public' and tablename = 'team_access' and cmd <> 'SELECT' and coalesce(qual, '') not like '%is_ceo_role%' ) then 'OK' else 'PROBLEM - check the team_access policies, or 0044 did not run' end as result; select '3. contracts follow the Contracts switch' as check, case when exists ( select 1 from pg_policies where schemaname = 'public' and tablename = 'documents' and policyname = 'documents: staff assigned' and qual like '%staff_can(''contracts''%' ) and exists ( select 1 from pg_policies where schemaname = 'storage' and tablename = 'objects' and policyname = 'client-documents: staff assigned' and qual like '%staff_can(''contracts''%' ) then 'OK' else 'PROBLEM - staff document access ignores the switch, or 0044 did not run' end as result; select '4. logins follow the Logins switch' as check, case when to_regclass('public.client_credentials') is null then 'skipped - 0039 has not run' when exists ( select 1 from pg_policies where schemaname = 'public' and tablename = 'client_credentials' and policyname = 'client_credentials: staff assigned' and qual like '%staff_can(''logins''%' ) then 'OK' else 'PROBLEM - staff login access ignores the switch, or 0044 did not run' end as result; select '5. money is read-only, and only with the Money switch' as check, case when exists ( select 1 from pg_policies where schemaname = 'public' and tablename = 'invoices' and policyname = 'invoices: staff read when allowed' and cmd = 'SELECT' and qual like '%staff_can(''money''%' ) and not exists ( select 1 from pg_policies where schemaname = 'public' and tablename in ('invoices', 'client_accounts') and qual like '%staff%' and cmd <> 'SELECT' ) then 'OK' else 'PROBLEM - check the staff invoice policy, or 0044 did not run' end as result; select '6. a client''s history follows the switches' as check, case when exists ( select 1 from pg_policies where schemaname = 'public' and tablename = 'client_activity' and policyname = 'client_activity: staff assigned' and qual like '%staff_can(''money''%' ) and exists ( select 1 from pg_policies where schemaname = 'public' and tablename = 'client_activity' and policyname = 'client_activity: videographer read assigned' and qual like '%account%' ) then 'OK' else 'PROBLEM - check the client_activity policies, or 0044 did not run' end as result; select '7. switches set so far' as check, case when to_regclass('public.team_access') is null then 'none - 0044 has not run' else (xpath('/row/n/text()', query_to_xml( 'select count(*) as n from public.team_access', false, true, '')))[1]::text || ' staff member(s) changed from the starting point (contracts and logins on, money off)' end as result;
